1	import type { DataPoint } from "./types";
2	
3	/* All series share a common time axis (30-minute intervals, ~1 day of
4	 * history split into a "previous" half and a "current" half so idle-state
5	 * cards can show period-over-period change) so hovering conceptually lines
6	 * up across cards, even though each card manages its own hover state. */
7	const INTERVAL_SECONDS = 1800;
8	const POINTS_PER_PERIOD = 24;
9	const BASE_TIME =
10	  Math.floor(Date.UTC(2026, 4, 9, 0, 0, 0) / 1000) -
11	  INTERVAL_SECONDS * POINTS_PER_PERIOD;
12	
13	function withTime<T extends Record<string, number>>(values: T[]): DataPoint[] {
14	  return values.map((value, i) => ({
15	    time: BASE_TIME + INTERVAL_SECONDS * i,
16	    ...value,
17	  }));
18	}
19	
20	/* ─── CPU Utilization — % used, previous period (idx 0-23) + current (24-47).
21	 * The current period's average sits above the 80% warning threshold (not
22	 * just individual spikes) so the elevated color shows by default, before
23	 * any hovering — a server that's been running hot, not just briefly busy. */
24	export const cpuData: DataPoint[] = withTime(
25	  [
26	    58, 60, 63, 61, 59, 62, 65, 68, 70, 66, 63, 61, 59, 62, 64, 67, 69, 65, 62,
27	    60, 63, 66, 68, 64,
28	    // current period
29	    76, 79, 82, 85, 87, 84, 81, 78, 80, 88, 91, 93, 87, 82, 80, 77, 75, 78, 81,
30	    84, 86, 83, 80, 89,
31	  ].map((cpu) => ({ cpu })),
32	);
33	
34	/* ─── RAM usage — bytes used out of 16 GB total.
35	 *
36	 * Real server memory graphs are a "sawtooth": usage climbs as the app
37	 * allocates and caches, then drops sharply when garbage collection (or a
38	 * cache eviction) reclaims it, then climbs again — not a smooth ramp and
39	 * not a symmetric wobble. generateSawtoothGB builds a handful of
40	 * rise-then-drop cycles of varying length/height, each with small
41	 * point-to-point jitter layered on top of the climb (allocator noise,
42	 * background processes), rather than hand-typing every value. */
43	const GB = 1024 * 1024 * 1024;
44	
45	interface SawtoothCycle {
46	  /** How many points this rise-then-drop cycle spans. */
47	  length: number;
48	  /** GB level the cycle climbs to just before it drops. */
49	  peakGB: number;
50	  /** GB level the cycle drops back down to after the peak. */
51	  floorGB: number;
52	}
53	
54	function generateSawtoothGB(cycles: SawtoothCycle[], seed = 1): number[] {
55	  const values: number[] = [];
56	  // Simple deterministic PRNG (mulberry32) so the "randomness" is stable
57	  // across reloads instead of shifting every time this module re-evaluates.
58	  let state = seed;
59	  const jitter = (amplitude: number) => {
60	    state = (state * 1664525 + 1013904223) >>> 0;
61	    return ((state / 0xffffffff) * 2 - 1) * amplitude;
62	  };
63	
64	  for (const { length, peakGB, floorGB } of cycles) {
65	    const start = values.at(-1) ?? floorGB;
66	    for (let i = 0; i < length; i++) {
67	      const t = i / (length - 1);
68	      const climbing = start + (peakGB - start) * t;
69	      values.push(Math.round((climbing + jitter(0.15)) * 100) / 100);
70	    }
71	    // Sharp GC-style drop at the end of the cycle, not a gradual descent.
72	    values.push(Math.round((floorGB + jitter(0.1)) * 100) / 100);
73	  }
74	  return values;
75	}
76	
77	/* Each cycle contributes (length + 1) points (the climb, plus one sharp
78	 * drop point at the end) — the two groups below sum to 24 points each so
79	 * the 48-point total splits evenly at the midpoint, matching every other
80	 * series and the "previous period vs. current period" comparison logic
81	 * every card relies on. */
82	export const ramData: DataPoint[] = withTime(
83	  generateSawtoothGB(
84	    [
85	      { length: 7, peakGB: 13.6, floorGB: 11.4 },
86	      { length: 6, peakGB: 14.1, floorGB: 11.8 },
87	      { length: 8, peakGB: 13.9, floorGB: 12.0 },
88	      // current period — same climb/drop pattern, trending a bit higher
89	      { length: 7, peakGB: 14.4, floorGB: 12.2 },
90	      { length: 6, peakGB: 14.9, floorGB: 12.6 },
91	      { length: 8, peakGB: 14.7, floorGB: 12.4 },
92	    ],
93	    7,
94	  ).map((gb) => ({ memory: gb * GB })),
95	);
96	export const RAM_TOTAL_BYTES = 16 * GB;
97	
98	/* ─── Disk space — static snapshot, no chart. Values live directly on the card. */
99	export const diskSpace = {
100	  usedGB: 186,
101	  totalGB: 200,
102	  percentUsed: 93,
103	  growthGBPerDay: 1.5,
104	  projectedFullDate: "Jun 26, 2026",
105	  projectedDaysLeft: 9,
106	};
107	
108	/* ─── Shared deterministic PRNG + diurnal-curve helper ───────────────────
109	 * Both Bandwidth and Network speed follow the same real-world shape: low
110	 * overnight (~1am-10am), rising through the day, peaking in the evening
111	 * "internet rush hour" (~6-10pm) at roughly 1.5-2x the daily average, per
112	 * published traffic-pattern research — not flat noise around a baseline. */
113	function makeJitter(seed: number) {
114	  let state = seed;
